/* ============================================================
   أطياب الجاسم (React) — صفحة «قيد الصيانة» (MaintenancePage)

   تُعرض لأي مسار غير معروف، وللصفحات التي لم تُجهَّز بعد: تعرض اسم
   الصفحة المطلوب (من ATYAB_PAGES إن كان معروفاً) مع زرّين للعودة إلى
   العطور أو إلى الملف الشخصي، وملاحظة مؤقتة.

   ★ اسم الصفحة يُقرأ من الرابط نفسه — useParams (/:key) أو بقية المسار
     غير المطابق (params["*"]) في مسار الالتقاط "*" — فلا يمرّر App
     أي props إلى الصفحة.
   ============================================================ */

import { Link, useParams } from "react-router-dom";
import { PATHS, maintenancePath, pathOf } from "../routes.js";
import { usePageMeta } from "../usePageMeta.js";
import { ATYAB_PAGES } from "../data/appConfig.js";
import { Icon } from "../components/Source/Icons.jsx";

function hasOwn(obj, key) {
  return Object.prototype.hasOwnProperty.call(obj, key);
}

/* نبحث عن تسمية الصفحة: بالمفتاح مباشرة، أو بصفحة تشير إلى نفس المسار */
function labelFor(key) {
  const pages = ATYAB_PAGES || {};
  if (key && pages[key] && pages[key].label) return pages[key].label;
  const wanted = key ? maintenancePath(key) : PATHS.maintenance;
  for (const k in pages) {
    if (!hasOwn(pages, k)) continue;
    if (pages[k].target && pathOf(pages[k].target) === wanted) return pages[k].label || "";
  }
  for (const j in pages) {
    if (!hasOwn(pages, j)) continue;
    if (pages[j].target && pathOf(pages[j].target) === "/" + key) return pages[j].label || "";
  }
  return "";
}

export default function MaintenancePage() {
  const params = useParams();
  const key = params.key || params["*"] || "";
  const label = labelFor(key);

  usePageMeta({ route: "maintenance", titleAr: "قيد الصيانة", titleEn: "Under maintenance" });

  return (
    <section className="container view mt" id="maintenanceView">
      <div className="mt-card">
      <div className="mt-inner">
        <span className="mt-badge">
          <Icon name="wrench" strokeWidth={1.8} />
        </span>
        <h1 className="mt-title">
          {label ? (
            <>
              صفحة <span className="mt-page">{label}</span> قيد الصيانة
            </>
          ) : (
            "هذه الصفحة قيد الصيانة"
          )}
        </h1>
        <p className="mt-text">
          نعمل حالياً على تجهيز هذه الصفحة على أكمل وجه. في الأثناء يمكنك تصفّح العطور والبخور وإتمام طلبك بشكل طبيعي.
        </p>

        <div className="mt-actions">
          <Link className="btn-primary" to={PATHS.perfumes}>
            <Icon name="home" strokeWidth={1.8} />
            <span>تصفّح العطور الآن</span>
          </Link>
          <Link className="btn-ghost" to={PATHS.profile}>
            <Icon name="user" strokeWidth={1.8} />
            <span>ملفي الشخصي</span>
          </Link>
        </div>

        <div className="mt-track" aria-hidden="true">
          <i />
        </div>

        <p className="mt-note">
          هذه صفحة مؤقتة، وسيتم ربطها بالصفحة الأصلية قريباً.
          {key ? <span className="mt-note-id"> معرّف الربط: {key}</span> : null}
        </p>
      </div>
      </div>
    </section>
  );
}
